/* Tiny parachute pop: local timed arcade rounds, mouse and Quest laser input. */
(()=>{
class ParachuteRound{
 constructor(best=0){this.best=best;this.reset()}
 reset(){this.score=0;this.combo=0;this.hits=0;this.missed=0;this.remaining=60;this.active=true}
 hit(){if(!this.active)return 0;this.combo++;this.hits++;const points=10*Math.min(5,1+Math.floor((this.combo-1)/3));this.score+=points;return points}
 miss(){if(this.active){this.missed++;this.combo=0}}
 advance(seconds){if(!this.active)return;this.remaining=Math.max(0,this.remaining-seconds);if(!this.remaining){this.active=false;this.best=Math.max(this.best,this.score)}}
}
window.ParachuteRound=ParachuteRound;
AFRAME.registerComponent('parachute-arcade',{
 init(){this.muted=false;try{this.muted=localStorage.getItem('globiquest.parachutes.muted')==='true'}catch{}this.soundVoices=new Set();this.targets=[];this.bursts=[];this.elapsed=0;this.spawnClock=0;this.lastHud=-1;this.onHidden=()=>{this.paused=document.hidden};document.addEventListener('visibilitychange',this.onHidden);this.onEscape=e=>{if(e.key==='Escape'&&this.open)this.close()};window.addEventListener('keydown',this.onEscape)},
 start(){if(!this.open)this.worldPlayWasVisible=document.getElementById('worldPlay')?.object3D.visible??true;window.globiquest.closeScope?.();window.globiquest.stopHandLab?.();window.globiquest.closeTravel?.();window.globiquest.closePortal?.();window.globiquest.closeWaterView?.();this.clear();let best=0;try{best=Number(localStorage.getItem('globiquest.parachutes.best'))||0}catch{}this.xrRound=this.el.sceneEl.is('vr-mode');this.round=new ParachuteRound(best);document.getElementById('mapRoot')?.components?.['bimanual-globe']?.releaseAll();document.getElementById('earthRoot')?.components?.['globe-rotation']?.release();window.globiquest.globePatch?.clear?.();this.open=true;this.elapsed=0;this.spawnClock=0;this.paused=false;this.lastHud=-1;window.globiquest.setWorkspace('home',true);window.globiquest.closeScope?.();document.getElementById('worldPlay')?.setAttribute('visible',false);for(const id of ['mapRoot','destination'])document.getElementById(id).setAttribute('visible',false);this.hud();this.unlockSound();this.spawn();if(this.xrRound)window.globiquest.presentParachutes?.(this)},
 clear(){this.stopSounds();for(const t of this.targets)t.el.remove();for(const b of this.bursts)b.el.remove();this.targets=[];this.bursts=[];if(this.board){dispose(this.board);this.board.remove();this.board=null}},
 close(){const wasOpen=this.open;if(this.round)this.round.active=false;this.open=false;this.clear();window.globiquest.dismissParachutes?.();if(wasOpen)document.getElementById('worldPlay')?.setAttribute('visible',this.worldPlayWasVisible??true);window.globiquest.refreshWorkspace();},
 hud(){const T=AFRAME.THREE;if(!this.board){this.board=entity('a-entity',{id:'parachuteHUD',position:this.xrRound?'0 2.55 .25':'0 3.6 .25',scale:this.xrRound?'.68 .68 .68':'1 1 1'},this.el);this.hudCanvas=document.createElement('canvas');this.hudCanvas.width=1024;this.hudCanvas.height=256;this.hudTexture=new T.CanvasTexture(this.hudCanvas);this.hudTexture.colorSpace=T.SRGBColorSpace;window.GlobiquestPanelStyle?.texture(this.hudTexture,this.el.sceneEl);const plane=entity('a-plane',{width:2.8,height:.7,'data-canvas':'true',material:'shader:flat; transparent:true; side:double',class:'interactive'},this.board);const apply=()=>{const mesh=plane.getObject3D('mesh');if(mesh){mesh.material.map=this.hudTexture;mesh.material.needsUpdate=true}};plane.addEventListener('loaded',apply,{once:true});if(plane.hasLoaded)apply();window.GlobiquestPanelInput.bind(plane,1024,256,[{x:620,y:16,w:225,h:48,label:'Toggle hit sound',action:()=>this.toggleMute()},{x:865,y:16,w:122,h:48,label:'Close game',action:()=>this.close()},{x:30,y:75,w:964,h:163,label:'Play again',action:()=>{if(!this.round.active)this.start()}}])}const r=this.round,c=this.hudCanvas.getContext('2d'),font='-apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Inter, Arial, sans-serif';c.clearRect(0,0,1024,256);c.fillStyle='rgba(250,251,253,.97)';c.beginPath();c.roundRect(1,1,1022,254,34);c.fill();c.strokeStyle='#dbe0e6';c.lineWidth=2;c.stroke();window.GlobiquestPanelStyle?.frame(c,1024,256,{header:68,radius:34});c.fillStyle='#edf0f4';c.beginPath();c.roundRect(865,16,122,48,17);c.fill();c.fillStyle='#394659';c.font='500 24px '+font;c.textAlign='center';c.fillText('Close',926,48);c.fillStyle='#edf0f4';c.beginPath();c.roundRect(620,16,225,48,17);c.fill();c.fillStyle='#394659';c.fillText(this.muted?'Sound: Off':'Sound: On',732,48);c.textAlign='left';c.fillStyle='#697383';c.font='500 27px '+font;c.fillText(r.active?'Parachute Pop':'Round complete',126,48);c.fillStyle='#1d1d1f';c.font='600 79px '+font;c.fillText(String(r.score),44,143);const scoreWidth=c.measureText(String(r.score)).width;c.fillStyle='#737b87';c.font='400 28px '+font;c.fillText('points',60+scoreWidth,140);c.textAlign='right';c.fillStyle='#1d1d1f';c.font='500 52px '+font;c.fillText(r.active?Math.ceil(r.remaining)+'s':'Well played',946,140);c.textAlign='left';c.fillStyle='#626c79';c.font='400 27px '+font;c.fillText(r.active?r.combo+' streak  ·  Best '+r.best:r.hits+' hits  ·  Best '+r.best,44,216);c.textAlign='right';c.font='500 25px '+font;c.fillText(r.active?'Point and pop':'Select to play again',946,216);this.hudTexture.needsUpdate=true;},
 spawn(){if(this.targets.length>=6)return;const colors=['#f3a5ba','#9ccfea','#f3ce80','#b9a3e5','#9bd0b7','#f0b49b'];const x=this.xrRound?Math.random()*2.2-.5:(Math.random()-.5)*3.6,y=(this.xrRound?1.65:2.5)+Math.random()*.45,z=.3-Math.random()*.8;const root=entity('a-entity',{position:`${x} ${y} ${z}`},this.el);const color=colors[Math.floor(Math.random()*colors.length)];
 // A scalloped dome, four fine suspension lines and a smiling little parcel.
 for(let i=0;i<8;i++){entity('a-sphere',{radius:.23,'theta-length':90,'phi-start':i*45,'phi-length':45,'segments-width':5,'segments-height':10,color:i%2?'#fff5fc':color,material:'roughness:.75; side:double',class:'interactive'},root);const a=i/8*Math.PI*2;entity('a-sphere',{radius:.035,scale:'1 .55 1',position:`${Math.cos(a)*.212} -.006 ${Math.sin(a)*.212}`,color:i%2?'#fff5fc':color,class:'interactive'},root)}
 entity('a-sphere',{radius:.022,position:'0 .237 0',color:'#fff5fc'},root);
 const face=Math.floor(Math.random()*3),ink='#596078';
 for(const sx of [-1,1]){if(face===1&&sx===1){entity('a-torus',{radius:.021,'radius-tubular':.0045,arc:150,rotation:'0 0 15',position:'.065 .12 .205',color:ink},root)}else{entity('a-sphere',{radius:.012,scale:'1 1.3 .35',position:`${sx*.065} .12 .205`,color:ink},root);entity('a-sphere',{radius:.0035,position:`${sx*.065-.003} .125 .21`,color:'#ffffff'},root)}entity('a-sphere',{radius:.026,scale:'1 .48 .18',position:`${sx*.105} .079 .193`,color:'#f6a6be'},root)}
 if(face===2){entity('a-sphere',{radius:.018,scale:'.7 1 .3',position:'0 .075 .223',color:ink},root)}else entity('a-torus',{radius:.028,'radius-tubular':.0045,arc:155,rotation:'0 0 193',position:'0 .084 .218',color:ink},root);

 entity('a-torus',{radius:.224,'radius-tubular':.009,rotation:'90 0 0',color:'#fff5fc',class:'interactive'},root);
 for(const sx of [-1,1])for(const sz of [-1,1])entity('a-entity',{line:`start:${sx*.14} 0 ${sz*.14}; end:${sx*.055} -.28 ${sz*.055}; color:#fff3df`},root);
 entity('a-sphere',{radius:.09,scale:'1 .95 .88',position:'0 -.32 0',color:'#f6eaff','segments-width':20,'segments-height':14,material:'roughness:.85',class:'interactive'},root);
 entity('a-torus',{radius:.083,'radius-tubular':.006,rotation:'90 0 0',position:'0 -.32 0',color,class:'interactive'},root);
 for(const sx of [-1,1]){entity('a-sphere',{radius:.009,position:`${sx*.04} -.31 .07`,color:'#45536b'},root);entity('a-sphere',{radius:.003,position:`${sx*.04-.002} -.307 .078`,color:'#ffffff'},root);entity('a-sphere',{radius:.014,scale:'1 .55 .25',position:`${sx*.058} -.332 .07`,color:'#f0a6a8'},root);entity('a-sphere',{radius:.026,scale:'1 .55 .5',rotation:`0 0 ${sx*25}`,position:`${sx*.025} -.25 0`,color},root)}
 entity('a-torus',{radius:.022,'radius-tubular':.0035,arc:150,rotation:'0 0 195',position:'0 -.325 .073',color:'#45536b'},root);

 const target={el:root,x,y,z,age:0,speed:.14+Math.random()*.08,phase:Math.random()*6.28,done:false,color};root.addEventListener('click',()=>this.hit(target));this.targets.push(target);},
 hit(t){if(t.done||!this.round?.active||this.paused)return;t.done=true;const p=t.el.object3D.position.clone(),points=this.round.hit();this.burst(p,t.color,points);t.el.remove();this.targets=this.targets.filter(x=>x!==t);this.sound();this.hud();},
 burst(p,color,points){const root=entity('a-entity',{position:`${p.x} ${p.y} ${p.z}`},this.el);const particles=[];for(let i=0;i<10;i++){const e=entity('a-icosahedron',{radius:.025,color:i%2?color:'#ffe6a2'},root);particles.push({el:e,v:new AFRAME.THREE.Vector3((Math.random()-.5)*1.4,Math.random()*.8,(Math.random()-.5)*.6)})}entity('a-text',{value:'+'+points,align:'center',color:'#28534a',width:1.1,position:'0 .2 .1'},root);this.bursts.push({el:root,particles,age:0});},
 async unlockSound(){if(this.muted)return false;try{this.audio ||=new (window.AudioContext||window.webkitAudioContext)();if(!this.soundMaster){this.soundMaster=this.audio.createGain();this.soundMaster.gain.value=.26;this.soundMaster.connect(this.audio.destination)}await this.audio.resume();return !this.muted&&this.audio.state==='running'}catch{return false}},
 toggleMute(){this.muted=!this.muted;try{localStorage.setItem('globiquest.parachutes.muted',String(this.muted))}catch{}if(this.muted)this.stopSounds();else this.unlockSound();this.hud()},
 stopSounds(){for(const voice of this.soundVoices||[]){try{voice.osc.stop()}catch{}voice.osc.disconnect();voice.gain.disconnect()}this.soundVoices?.clear()},
 async sound(){if(this.muted||!this.open)return;const round=this.round;if(!await this.unlockSound()||!this.open||this.round!==round)return;const audio=this.audio,t=audio.currentTime,pitch=1+Math.min(round.combo,12)*.015;for(const [type,from,to,volume,duration,offset] of [['triangle',210,58,.72,.15,0],['sine',1047*pitch,1047*pitch,.32,.22,.015],['sine',1568*pitch,1568*pitch,.22,.28,.065],...(round.combo%5===0?[['sine',2093,2093,.23,.32,.115]]:[])]){const osc=audio.createOscillator(),gain=audio.createGain(),start=t+offset;osc.type=type;osc.frequency.setValueAtTime(from,start);osc.frequency.exponentialRampToValueAtTime(to,start+duration*.65);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.008);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain);gain.connect(this.soundMaster);const voice={osc,gain};this.soundVoices.add(voice);osc.onended=()=>{osc.disconnect();gain.disconnect();this.soundVoices.delete(voice)};osc.start(start);osc.stop(start+duration+.01)}if(!this.popBuffer){this.popBuffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*.075),audio.sampleRate);const data=this.popBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/data.length,2)}const burst=audio.createBufferSource(),gain=audio.createGain();burst.buffer=this.popBuffer;gain.gain.setValueAtTime(.5,t);gain.gain.exponentialRampToValueAtTime(.0001,t+.075);burst.connect(gain);gain.connect(this.soundMaster);const voice={osc:burst,gain};this.soundVoices.add(voice);burst.onended=()=>{burst.disconnect();gain.disconnect();this.soundVoices.delete(voice)};burst.start(t);burst.stop(t+.08);while(this.soundVoices.size>24){const oldest=this.soundVoices.values().next().value;try{oldest.osc.stop()}catch{}oldest.osc.disconnect();oldest.gain.disconnect();this.soundVoices.delete(oldest)}},
 tick(time,delta){if(!this.open||this.paused)return;const dt=Math.min(delta/1000,.1);this.elapsed+=dt;const r=this.round;if(r.active){r.advance(dt);if(!r.active){for(const t of this.targets)t.el.remove();this.targets=[];try{localStorage.setItem('globiquest.parachutes.best',String(r.best))}catch{}this.hud()}else{this.spawnClock-=dt;if(this.spawnClock<=0){this.spawn();this.spawnClock=.8+Math.random()*.45}for(const t of [...this.targets]){t.age+=dt;t.el.object3D.position.set(t.x+Math.sin(t.age*1.5+t.phase)*.18,t.y-t.age*t.speed,t.z);t.el.object3D.rotation.z=Math.sin(t.age*2+t.phase)*.12;if(t.el.object3D.position.y<(this.xrRound?.25:.75)){t.done=true;t.el.remove();this.targets=this.targets.filter(x=>x!==t);r.miss();this.hud()}}if(Math.ceil(r.remaining)!==this.lastHud){this.lastHud=Math.ceil(r.remaining);this.hud()}}}for(const b of [...this.bursts]){b.age+=dt;for(const p of b.particles){p.el.object3D.position.addScaledVector(p.v,dt);p.v.y-=dt; p.el.object3D.scale.setScalar(Math.max(0,1-b.age/.65))}if(b.age>.7){b.el.remove();this.bursts=this.bursts.filter(x=>x!==b)}}},
 configureView(){if(!this.open)return;const xr=this.el.sceneEl.is('vr-mode');if(xr!==this.xrRound){const shift=xr?-.85:.85;for(const t of this.targets){t.y+=shift;t.el.object3D.position.y+=shift}this.xrRound=xr;if(this.board){this.board.setAttribute('position',xr?'0 2.55 .25':'0 3.6 .25');this.board.setAttribute('scale',xr?'.68 .68 .68':'1 1 1')}}if(xr)window.globiquest.presentParachutes?.(this);else window.globiquest.dismissParachutes?.()},
 remove(){this.clear();document.removeEventListener('visibilitychange',this.onHidden);window.removeEventListener('keydown',this.onEscape);this.audio?.close()}
});
const setup=()=>{const root=entity('a-entity',{'parachute-arcade':''},scene);const start=()=>root.components['parachute-arcade']?.start();const dock=document.getElementById('spatialDock');const button=document.createElement('button');button.innerHTML='<span>♧</span>Parachute Pop';button.onclick=start;dock.append(button);dock.addEventListener('click',e=>{if(!button.contains(e.target)&&root.components['parachute-arcade']?.open)root.components['parachute-arcade'].close()},true);window.globiquest.parachutes={start,get component(){return root.components['parachute-arcade']},get open(){return !!root.components['parachute-arcade']?.open},close:()=>root.components['parachute-arcade']?.close()};};if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});
})();
